<?php declare(strict_types=1); final class MessageController extends Controller { public function index(): void { AuthMiddleware::handle();$id=(int)Session::get('user_id');$s=Database::connection()->prepare('SELECT m.*,p.display_name AS sender_name FROM messages m LEFT JOIN profiles p ON p.user_id=m.sender_id WHERE m.sender_id=:id OR m.receiver_id=:id2 ORDER BY m.created_at DESC LIMIT 100');$s->execute(['id'=>$id,'id2'=>$id]);$this->view('messages/index',['title'=>'پیام‌ها','messages'=>$s->fetchAll()],Session::get('role')==='employer'?'employer':'dashboard'); } public function send(): void { AuthMiddleware::handle();if(!CSRF::verify($_POST['_csrf']??null)){$this->redirect('/messages');}$receiver=(int)$_POST['receiver_id'];$content=trim((string)$_POST['content']);if($receiver>0&&$content!==''){$s=Database::connection()->prepare('INSERT INTO messages(sender_id,receiver_id,content) VALUES(:sender,:receiver,:content)');$s->execute(['sender'=>(int)Session::get('user_id'),'receiver'=>$receiver,'content'=>$content]);}$this->redirect('/messages'); } }